'use strict';

// APG catalogue eBay product-hero registry v2.1.
//
// This file is the only non-pilot source allowed to activate an eBay listing image in a
// product-page hero. Rows are generated by the controlled eBay AU enrichment evaluator,
// independently re-checked by the strict hero guard at render time, and expire after the
// runtime freshness window. Public product-page requests must never perform Browse API
// discovery or detail calls.
//
// eBay Content remains retailer-scoped. Nothing in this registry grants APG ownership of an
// image, writes eBay imagery into canonical Product.image, or changes recommendation scoring.

const VERSION='2.1';
const MARKETPLACE='EBAY_AU';
const SOURCE='eBay Buy Browse API';

// Populated only from exact, detail-verified, whole-product results produced by the governed
// evaluator. It is intentionally empty while the normal Browse quota is exhausted. The site
// therefore fails closed to the existing APG brand placeholder rather than using stale or
// uncertain retailer imagery.
const offers=Object.freeze({});

function clean(value){return String(value==null?'':value).trim();}
function complete(row){
  if(!row||typeof row!=='object'||row.status!=='accept'||!row.accepted)return false;
  const a=row.accepted;
  if(!clean(row.slug)||clean(a.marketplaceId)!==MARKETPLACE||clean(a.source)!==SOURCE)return false;
  if(a.detailVerified!==true||a.exactModel!==true||a.recommendationWeight!==0||row.recommendationWeight!==0)return false;
  if(!['detail-model-evidence','detail-title-model'].includes(clean(a.verificationLevel)))return false;
  if(!clean(a.itemId)||!clean(a.legacyItemId)||!clean(a.title)||!clean(a.condition))return false;
  if(!a.price||clean(a.price.currency)!=='AUD'||!clean(a.price.value))return false;
  if(!/^https:\/\/i\.ebayimg\.com\//i.test(clean(a.imageUrl)))return false;
  if(!/^https:\/\/www\.ebay\.com\.au\/itm\//i.test(clean(a.itemWebUrl)))return false;
  if(!clean(row.observedAt)||!Number.isFinite(Date.parse(row.observedAt)))return false;
  return true;
}
function forSlug(slug){
  const row=offers[clean(slug)]||null;
  return complete(row)?row:null;
}

module.exports={VERSION,MARKETPLACE,SOURCE,offers,complete,forSlug};
